# SPDX-License-Identifier: MIT
#
# bovnar -> pint unit bridge table.
#
# The first version was generated by a tool; it is HAND-MAINTAINED now, and the
# tool is gone. Add a unit by adding its row and, if pint has no definition for
# it or pint's differs, its definition above. The tests are what verify the
# result: TestUnitTableIntegrity re-derives every unit's dimension and magnitude
# from bovnar and asserts pint reproduces both, and
# TestPintAgreesWithBovnarOnWhatConverts asserts pint refuses every conversion
# bovnar refuses, so an entry that is wrong or missing fails there rather than
# shipping quietly.
#
# Verified against pint 0.25.3:
#   every non-currency base unit reproduces bovnar's dimension AND magnitude
#   exactly (incl. the custom definitions + 6 affine temperature scales).
#   Units carrying a bovnar QUANTITY KIND (bit, byte, dB, Np, pH, the five
#   turbidity scales, PSU, and the angle family) get their own pint dimension
#   instead of pint's native, so pint refuses what bovnar refuses — see
#   KIND_DIMENSIONS. What survives that is listed in SEMANTIC_CAVEATS.
#
# 216 currencies (fiat + crypto + precious metals) have no pint dimension, so each
# is registered as its OWN independent dimension [currency_<CODE>] with the ISO/
# crypto code as the reference unit. Consequences (all verified):
#   * cross-currency .to() raises pint.DimensionalityError — never a silent 1:1
#     conversion (a single shared [currency] dimension WOULD silently convert,
#     e.g. 100 USD -> 100 EUR, so that encoding is deliberately rejected);
#   * same-currency arithmetic works (3 USD + 2 USD = 5 USD);
#   * is_currency_unit() detects them via the [currency_ dimension-name prefix.
# Cross-rate conversion, if ever wanted, belongs in an explicit pint Context.
#
# Keyed on the bovnar BaseUnit *integer code* (stable, mirrors the C enum), NOT
# on the serialized symbol: bovnar symbols collide with pint prefix+unit parses
# (e.g. bovnar "b"=bit vs pint "b"=barn, "R"=roentgen vs pint gas constant).
"""bovnar <-> pint unit translation tables and registry builder."""

from __future__ import annotations

import math


# --- custom physical-unit definitions to register on a pint UnitRegistry ------
# Derived from bovnar's own SI dimension vector + conversion factor, so each
# reproduces bovnar's magnitude exactly (and sidesteps pint's CGS-Gaussian
# fractional dimensions for gauss/maxwell/oersted).
BOVNAR_PINT_DEFINITIONS: list[str] = [
    # pint defines fathom/rod/chain/furlong/league/acre from its SURVEY foot
    # (1200/3937 m), while bovnar uses the international foot -- a silent 2 ppm
    # magnitude error (4 ppm for acre, being an area). pint's foot, mile, yard
    # and inch are already international and agree exactly, so only these six
    # need their own definition.
    'bvnr_fathom = 1.8288 * meter',
    'bvnr_rod = 5.0292 * meter',
    'bvnr_chain = 20.1168 * meter',
    'bvnr_furlong = 201.168 * meter',
    'bvnr_league = 4828.032 * meter',
    'bvnr_acre = 4046.8564224 * meter**2',
    'bvnr_therm = 105480400.0 * meter**2 * kilogram * second**-2',
    'bvnr_rpm = 0.016666666666666666 * second**-1',
    'bvnr_cable = 185.2 * meter',
    'bvnr_delisle = -0.6666666666666666 * kelvin; offset: 373.15',
    'bvnr_doppelzentner = 100.0 * kilogram',
    'bvnr_gauss = 0.0001 * kilogram * second**-2 * ampere**-1',
    'bvnr_german_mile = 7420.44 * meter',
    # gradian (gon): pint's native `gradian` alias is absent in some pint
    # versions, so define it from bovnar's factor (pi/200 rad) for stability.
    'bvnr_klafter = 1.88312 * meter',
    'bvnr_lot = 0.015625 * kilogram',
    'bvnr_maxwell = 1e-08 * meter**2 * kilogram * second**-2 * ampere**-1',
    'bvnr_morgen = 2553.22 * meter**2',
    'bvnr_newton_temp = 3.0303030303030303 * kelvin; offset: 273.15',
    'bvnr_oersted = 79.57747154594767 * meter**-1 * ampere',
    'bvnr_per_cent_mille = 1e-05',
    'bvnr_per_myriad = 0.0001',
    'bvnr_pfund = 0.5 * kilogram',
    # Water hardness: amount concentration of alkaline-earth ions. pint has no
    # hardness units at all, so all six come from bovnar's own factors.
    'bvnr_german_hardness = 0.17832623000517145 * mole * meter**-3',
    'bvnr_english_hardness = 0.1424151981625826 * mole * meter**-3',
    'bvnr_french_hardness = 0.09991407389644906 * mole * meter**-3',
    'bvnr_russian_hardness = 0.024951344877488894 * mole * meter**-3',
    'bvnr_american_hardness = 0.009991407389644906 * mole * meter**-3',
    'bvnr_val = 0.5 * mole',
    'bvnr_grains_per_gallon = 0.17103352162411276 * mole * meter**-3',
    'bvnr_conductivity_factor = 0.01 * siemens * meter**-1',
    'bvnr_phot = 10000.0 * meter**-2 * candela',
    'bvnr_ppb = 1e-09',
    'bvnr_prussian_elle = 0.666937625 * meter',
    'bvnr_prussian_fuss = 0.313853 * meter',
    'bvnr_prussian_line = 0.002179534722222222 * meter',
    'bvnr_prussian_rute = 3.76624 * meter',
    'bvnr_prussian_zoll = 0.026154416666666666 * meter',
    'bvnr_quintal = 100.0 * kilogram',
    # Réaumur: pint's `degree_Reaumur` definition differs across versions
    # (some use a 4/5 scale, giving 100 degRe -> 353.15 K instead of 398.15 K),
    # so pin it to bovnar's factor (5/4) + offset (273.15 K).
    'bvnr_reaumur = 1.25 * kelvin; offset: 273.15',
    'bvnr_romer = 1.9047619047619047 * kelvin; offset: 258.8642857142857',
    'bvnr_scheffel = 0.054961 * meter**3',
    'bvnr_var = 1.0 * meter**2 * kilogram * second**-3',
    'bvnr_zentner = 50.0 * kilogram',
]


