# --- quantity kinds: units bovnar refuses to interconvert -------------------
# bovnar tracks "quantity kinds" for units that carry NO SI dimension yet are
# not interchangeable with a plain number or with each other — bit vs byte, an
# angle vs a count, dB vs Np vs pH, and one kind per turbidity method. pint has
# no such concept: to it they are all dimensionless, so it would convert an NTU
# into an FNU or a pH into a percentage, exactly the answer bovnar exists to
# refuse.
#
# The fix is the one the currency table already uses below: give each kind its
# own pint DIMENSION. pint then enforces bovnar's rule natively —
# DimensionalityError instead of a silent number — and conversions WITHIN a kind
# keep working (m~NTU -> NTU, ° -> rad, sr -> rad²), because that is what a
# shared dimension means.
#
# The cost, and it is a real one: these units no longer speak to pint's natives.
# A bovnar-derived byte will not convert to pint's `megabyte`, nor a bovnar
# radian to pint's `degree`. Pass isolate_kinds=False to build_registry() to get
# the old aliasing back, and with it pint's permissiveness.
#
# dB and Np deliberately do NOT use pint's logarithmic units: bovnar models them
# as linear tags (a value labelled dB, not a log-arithmetic type), and mapping
# them onto pint's log units would import semantics bovnar does not have.
KIND_DIMENSIONS: dict[str, str] = {
    'bvnr_bit':         'information_bit',
    'bvnr_byte':        'information_byte',
    'bvnr_decibel':     'log_decibel',
    'bvnr_neper':       'log_neper',
    'bvnr_ph_scale':    'ph_scale',
    'bvnr_ntu':         'turbidity_ntu',
    'bvnr_fnu':         'turbidity_fnu',
    'bvnr_ftu':         'turbidity_ftu',
    'bvnr_fau':         'turbidity_fau',
    'bvnr_jtu':         'turbidity_jtu',
    'bvnr_psu':         'practical_salinity',
    'bvnr_radian':      'angle',
}

# The angle kind is SHARED: degree -> radian is a conversion people legitimately
# want, and steradian really is radian², so these are defined from the reference
# rather than as dimensions of their own.
_ANGLE_DERIVED: list[str] = [
    'bvnr_degree = %.17g * bvnr_radian' % (math.pi / 180.0),
    'bvnr_gradian = %.17g * bvnr_radian' % (math.pi / 200.0),
    'bvnr_revolution = %.17g * bvnr_radian' % (2.0 * math.pi),
    'bvnr_arcminute = %.17g * bvnr_radian' % (math.pi / 10800.0),
    'bvnr_arcsecond = %.17g * bvnr_radian' % (math.pi / 648000.0),
    'bvnr_steradian = bvnr_radian ** 2',
]

# What isolate_kinds=False falls back to: pint's native where one exists, plain
# dimensionless where none does. This is bovnar's pre-isolation behaviour, kept
# for callers who need to interoperate with pint units from other code.
_KIND_NATIVE_FALLBACK: list[str] = [
    'bvnr_bit = bit',
    'bvnr_byte = byte',
    'bvnr_decibel = decibel',
    'bvnr_neper = neper',
    'bvnr_radian = radian',
    'bvnr_degree = degree',
    'bvnr_gradian = %.17g * radian' % (math.pi / 200.0),
    'bvnr_revolution = revolution',
    'bvnr_arcminute = arcminute',
    'bvnr_arcsecond = arcsecond',
    'bvnr_steradian = steradian',
    'bvnr_ph_scale = 1.0',
    'bvnr_ntu = 1.0',
    'bvnr_fnu = 1.0',
    'bvnr_ftu = 1.0',
    'bvnr_fau = 1.0',
    'bvnr_jtu = 1.0',
    'bvnr_psu = 1.0',
]

# --- semantic caveats: parse/label OK, but value semantics differ ------------
SEMANTIC_CAVEATS: dict[str, str] = {
    'DECIBEL': 'isolated as its own pint dimension, so the conversions bovnar refuses are refused there too. What remains is arithmetic: bovnar models dB as a linear tag, so pint will add two of them and the sum is not what a decibel means (20 dB is a ratio of 100, not twice 10 dB).',
    'NEPER': 'as DECIBEL: the label and the refusals survive, the logarithmic arithmetic does not.',
    'PH_SCALE': 'as DECIBEL. pH 7 is not "7 of" anything and pH 6 is ten times the concentration of pH 7, so summing or averaging pH values is meaningless in either library.',
    'VAL': 'bovnar val is the equivalent AS USED IN WATER ANALYSIS (divalent ions): 1 val = 0.5 mol. For a monovalent species an equivalent is 1 mol, which neither library can infer from the unit alone.',
}


